package com.jobpilot.job;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/jobs")public class JobController{private final JobService service;public JobController(JobService s){service=s;}@GetMapping List<JobDtos.JobView>list(){return service.list();}@PostMapping @ResponseStatus(HttpStatus.CREATED)JobDtos.JobView create(@Valid @RequestBody JobDtos.CreateJob d){return service.create(d);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable Long id){service.delete(id);}}
